def certificate_summary(items, observed_at, *, complete):
    unknown = {
        'state': 'unknown', 'earliestCertificateNotAfter': None,
        'renewalWindowStartsAt': None, 'secondsUntilEarliestExpiry': None,
    }
    if not complete or not items or any(
