// locking out the serving Node. Missing/incoherent/private state is refused.
func ObservePeerPolicyFloor(config node.Config, state, policy, certPath, keyPath, nonce string, servingPID int) (map[string]any, error) {
	rejected := errors.New("NODE-0041: authenticated actual peer floor unavailable")
	if !peerFloorNonce.MatchString(nonce) || certPath != filepath.Join(filepath.Dir(state), "node-cert.pem") || keyPath != filepath.Join(filepath.Dir(state), "node-key.pem") {
		return nil, rejected
	}
	certRaw, err := SafeFile(certPath, false)
	if err != nil {
		return nil, rejected
	}
	keyRaw, err := SafeFile(keyPath, true)
	if err != nil {
		return nil, rejected
	}
	pair, err := tls.X509KeyPair(certRaw, keyRaw)
	if err != nil || len(pair.Certificate) == 0 {
		return nil, rejected
	}
	cert, err := x509.ParseCertificate(pair.Certificate[0])
	key, ok := pair.PrivateKey.(ed25519.PrivateKey)
	now := time.Now()
	if err != nil || !ok || cert.IsCA || !hasUsage(cert, x509.ExtKeyUsageServerAuth) || len(cert.URIs) != 1 || cert.URIs[0].String() != Identity(config.TenantID, config.NodeID, config.Epoch) || now.Before(cert.NotBefore) || !now.Before(cert.NotAfter) {
		return nil, rejected
	}
	floor, err := node.ReadPeerPolicyFloor(state, policy, config)
	if err != nil {
		return nil, err
	}
	processHash, err := node.PeerFloorServingProcess(servingPID, state, policy, config, floor.JournalUID)
	if err != nil {
		return nil, err
	}
	executableHash, err := node.ServingExecutableSHA256(servingPID, floor.JournalUID)
	if err != nil {
		return nil, err
	}
	current, err := SafeFile(certPath, false)
	if err != nil || sha256.Sum256(current) != sha256.Sum256(certRaw) {
		return nil, rejected
	}
	currentKey, err := SafeFile(keyPath, true)
	if err != nil || sha256.Sum256(currentKey) != sha256.Sum256(keyRaw) {
		return nil, rejected
	}
	lastFloor, err := node.ReadPeerPolicyFloor(state, policy, config)
	if err != nil || lastFloor != floor {
		return nil, rejected
	}
	lastProcess, err := node.PeerFloorServingProcess(servingPID, state, policy, config, floor.JournalUID)
	if err != nil || lastProcess != processHash {
		return nil, rejected
	}
	lastExecutable, err := node.ServingExecutableSHA256(servingPID, floor.JournalUID)
	if err != nil || lastExecutable != executableHash {
		return nil, rejected
	}
	der := sha256.Sum256(cert.Raw)
	body := map[string]any{"schemaVersion": "saintvision-node-peer-policy-floor:2", "tenantId": config.TenantID, "nodeId": config.NodeID, "recoveryEpoch": config.Epoch, "nonce": nonce, "observedAt": now.Unix(), "certificateDER_SHA256": hex.EncodeToString(der[:]), "peerPolicyVersion": floor.Version, "peerPolicySHA256": floor.Hash, "floorSHA256": floor.FloorSHA256, "journalIdentitySHA256": floor.JournalIdentitySHA256, "journalUID": floor.JournalUID, "servingPID": servingPID, "servingProcessSHA256": processHash, "servingExecutableSHA256": executableHash, "plainServingProcess": true}
	raw, err := CanonicalPeerFloorBody(body)
	if err != nil {
		return nil, rejected
	}
	body["nodeSignature"] = hex.EncodeToString(ed25519.Sign(key, append([]byte(PeerFloorDomain), raw...)))
	return body, nil
}

// PinPeerPolicy persists an anti-rollback floor separately from allocation fences.
// Caller serializes policy updates; the journal process lock prevents other writers.
func (j *Journal) PinPeerPolicy(version int64, hash string) error {
	if version < 1 || version > 9007199254740991 || !hexID.MatchString(hash) {
		return errors.New("NODE-0041: invalid peer policy floor")
	}
	path := filepath.Join(j.root, ".peer-policy")
	var prior struct {
		Version int64
		Hash    string
	}
	next := struct {
		Version int64
		Hash    string
	}{version, hash}
	err := readPrivate(path, &prior)
	if os.IsNotExist(err) {
		return j.create(path, next)
	}
	if err != nil {
		return errors.New("NODE-0041: peer policy journal unavailable")
	}
	if prior.Version < 1 || !hexID.MatchString(prior.Hash) {
		return errors.New("NODE-0041: corrupt peer policy floor")
	}
	if version < prior.Version || (version == prior.Version && hash != prior.Hash) {
		return errors.New("NODE-0041: peer policy rollback rejected")
	}
	if next == prior {
		return nil
	}
	file, err := os.CreateTemp(j.root, ".peer-policy-")
	if err != nil {
		return err
	}
	raw, _ := json.Marshal(next)
	_, err = file.Write(raw)
	if err == nil {
		err = file.Sync()
	}
	name := file.Name()
	closeErr := file.Close()
	if err == nil {
		err = closeErr
	}
	if err == nil {
		err = os.Rename(name, path)
	}
	if err == nil {
		err = j.syncDir()
	}
	return err
}
